def _sentences(s):
    return [x for x in re.split(r"(?<=[.!?])\s+(?=[A-Z0-9“\"(])", s.strip()) if x]


def test():
    keys = {"skill", "name", "plain", "qs", "levels", "topics", "qa"}
    for slug, q in QUIZZES.items():
        assert set(q) <= keys and {"skill", "name", "plain", "qs"} <= set(q), (slug, set(q) ^ keys)
        qs = q["qs"]
        n = len(qs)
        assert n == 24, (slug, n)
        assert len({t for t, _, _, _ in qs}) == n, (slug, "a question is repeated")
        for t, opts, ok, why in qs:
            assert isinstance(t, str) and "?" in t, (slug, t)
            assert isinstance(opts, list) and len(opts) == 4 and len(set(opts)) == 4 and all(isinstance(o, str) and o.strip() for o in opts), (slug, t)
            assert isinstance(ok, int) and 0 <= ok < 4, (slug, t)
            assert isinstance(why, str) and why.rstrip().endswith((".", ")")) and 1 <= len(_sentences(why)) <= 3 and len(why) <= 330, (slug, t, why)
        # the right answer must not sit in one place: each position is used at least 3 times, none more than 9 of 24
        pos = [sum(1 for _, _, ok, _ in qs if ok == i) for i in range(4)]
        assert min(pos) >= 3 and max(pos) <= 9, (slug, pos)
        # levels: one per question, from LEVELS, and every level present at least 3 times
        lv = q["levels"]
        assert isinstance(lv, list) and len(lv) == n and set(lv) <= set(LEVELS), (slug, "levels", len(lv))
        assert all(lv.count(x) >= 3 for x in LEVELS), (slug, {x: lv.count(x) for x in LEVELS})
        # topics: one per question, from TOPICS[slug], and every allowed topic used at least once
        tp = q["topics"]
        allowed = TOPICS[slug]
        assert isinstance(tp, list) and len(tp) == n, (slug, "topics", len(tp))
        assert set(tp) <= set(allowed), (slug, set(tp) - set(allowed))
        assert set(allowed) <= set(tp), (slug, "unused topic", set(allowed) - set(tp))
        assert all(len(x) <= 24 for x in allowed) and len(set(allowed)) == len(allowed), (slug, allowed)
        # qa: 3-4 (question, answer) pairs; no percentages, so no invented statistics slip in
        qa = q["qa"]
        assert isinstance(qa, list) and 3 <= len(qa) <= 4, (slug, "qa", len(qa))
        for a, b in qa:
            assert isinstance(a, str) and a.endswith("?") and isinstance(b, str) and b.endswith(".") and "%" not in b, (slug, a)
        assert len({a for a, _ in qa}) == len(qa), (slug, "a qa question is repeated")
    assert set(TOPICS) == set(QUIZZES)
    print("ok", len(QUIZZES), "quizzes,", sum(len(q["qs"]) for q in QUIZZES.values()), "questions")


if __name__ == "__main__":
    test()
